// Parameters (mm)
plate_L = 114.0;
plate_W = 59.5;
plate_T = 0.8;

slot_L = 30;
slot_W = 10;
slot_end_r = slot_W/2;          // ensure true obround ends
slot_center_x_from_left = 15;
slot_center_y_from_bottom = 12;

$fn = 64;

// Base plate (non-centered for unambiguous "from left/bottom" placement)
module plate_body() {
    cube([plate_L, plate_W, plate_T], center=false);
}

// Obround slot (through-cut along Z)
module obround_slot_3d() {
    // Build in XY, then extrude in Z
    linear_extrude(height = plate_T + 2, center = true)
        hull() {
            translate([-(slot_L/2 - slot_end_r), 0]) circle(r = slot_end_r);
            translate([ +(slot_L/2 - slot_end_r), 0]) circle(r = slot_end_r);
        }
}

module plate_with_slot() {
    difference() {
        plate_body();

        // Place slot by its center measured from left/bottom edges of the plate
        translate([slot_center_x_from_left, slot_center_y_from_bottom, plate_T/2])
            obround_slot_3d();
    }
}

// Final
plate_with_slot();

// Rounded-rectangle stepped plate/bracket with 3-row keyhole/dogbone slots,
// shallow corner recess rings, and mid-side edge notches.
// Bounding box: 40 x 40 x 16 mm

$fn = 128;

// ---------------- Parameters ----------------
bb_x = 40.0;
bb_y = 40.0;
bb_z = 16.0;

corner_r = 6.0;

thin_t  = 8.0;
thick_t = 16.0;

boss_len_x = 14.0;          // thicker end length along +X

// Slots: 3 rows x 2 cols (arranged in three rows)
slot_rows = 3;
slot_cols = 2;
slot_pitch_y = 10.5;        // tighter so 3 rows read clearly within 40mm
slot_pitch_x = 16.0;
slot_center_x = 0.0;
slot_center_y = 0.0;

slot_major_len = 12.0;      // overall slot length (Y)
slot_tail_d    = 5.0;       // small end diameter
slot_head_d    = 7.0;       // large end diameter
slot_neck_w    = 4.0;       // neck width

// Corner recess "outline rings" (shallow annular pockets)
recess_outer_d = 10.0;
recess_ring_w  = 1.2;       // ring thickness
recess_depth   = 0.6;
recess_offset_from_corner = 8.0;

// Edge notches at mid-sides
edge_notch_w = 4.0;
edge_notch_d = 1.5;
edge_notch_h = 2.0;

eps = 0.02;
eps_overlap = 0.6;

// ---------------- Helpers ----------------
module rr2d(w, h, r) {
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(w/2 - r), sy*(h/2 - r)]) circle(r=r);
  }
}

module plate_solid() {
  // One connected solid: thin full plate + thick boss on +X end
  union() {
    // thin full footprint
    linear_extrude(height=thin_t, center=true)
      rr2d(bb_x, bb_y, corner_r);

    // thick boss region (adds thickness above thin plate)
    translate([0, 0, (thin_t/2) + (thick_t - thin_t)/2 - eps_overlap/2])
      linear_extrude(height=(thick_t - thin_t) + eps_overlap, center=true)
        intersection() {
          rr2d(bb_x, bb_y, corner_r);
          translate([bb_x/2 - boss_len_x/2, 0])
            square([boss_len_x + eps_overlap, bb_y + 2*eps_overlap], center=true);
        }
  }
}

module keyhole_dogbone_2d(major_len, head_d, tail_d, neck_w) {
  // 2D profile centered at origin, oriented along Y
  neck_len = max(0.01, major_len - head_d/2 - tail_d/2);

  union() {
    // neck
    square([neck_w, neck_len], center=true);

    // head circle (+Y)
    translate([0, (major_len/2 - head_d/2)]) circle(d=head_d);

    // tail circle (-Y)
    translate([0, -(major_len/2 - tail_d/2)]) circle(d=tail_d);

    // dogbone reliefs at transitions (subtle waist)
    translate([0, (major_len/2 - head_d/2) - (head_d/2 - neck_w/2)])
      circle(d=neck_w);
    translate([0, -(major_len/2 - tail_d/2) + (tail_d/2 - neck_w/2)])
      circle(d=neck_w);
  }
}

module slots_cut() {
  // Through-cut slots across full thick_t
  linear_extrude(height=thick_t + 2*eps, center=true)
    union() {
      for (r = [0:slot_rows-1]) {
        row = r - (slot_rows-1)/2;
        for (c = [0:slot_cols-1]) {
          col = c - (slot_cols-1)/2;
          translate([slot_center_x + col*slot_pitch_x,
                     slot_center_y + row*slot_pitch_y])
            keyhole_dogbone_2d(slot_major_len, slot_head_d, slot_tail_d, slot_neck_w);
        }
      }
    }
}

module corner_recess_rings_cut() {
  // Shallow annular recesses on BOTH faces (top and bottom)
  recess_inner_d = max(0.1, recess_outer_d - 2*recess_ring_w);

  for (sx = [-1, 1], sy = [-1, 1]) {
    x = sx*(bb_x/2 - recess_offset_from_corner);
    y = sy*(bb_y/2 - recess_offset_from_corner);

    // top face ring
    translate([x, y, thick_t/2 - recess_depth/2 + eps])
      linear_extrude(height=recess_depth + 2*eps, center=true)
        difference() {
          circle(d=recess_outer_d);
          circle(d=recess_inner_d);
        }

    // bottom face ring (on thin face)
    translate([x, y, -thin_t/2 + recess_depth/2 - eps])
      linear_extrude(height=recess_depth + 2*eps, center=true)
        difference() {
          circle(d=recess_outer_d);
          circle(d=recess_inner_d);
        }
  }
}

module mid_side_notches_cut() {
  // Small edge notches at mid-sides, cut into the perimeter
  // Place them in the thin region so they show in side views.
  zc = -thin_t/2 + edge_notch_h/2;

  // +X and -X sides
  translate([ bb_x/2 - edge_notch_d/2 + eps, 0, zc])
    cube([edge_notch_d + 2*eps, edge_notch_w, edge_notch_h + 2*eps], center=true);
  translate([-bb_x/2 + edge_notch_d/2 - eps, 0, zc])
    cube([edge_notch_d + 2*eps, edge_notch_w, edge_notch_h + 2*eps], center=true);

  // +Y and -Y sides
  translate([0,  bb_y/2 - edge_notch_d/2 + eps, zc])
    cube([edge_notch_w, edge_notch_d + 2*eps, edge_notch_h + 2*eps], center=true);
  translate([0, -bb_y/2 + edge_notch_d/2 - eps, zc])
    cube([edge_notch_w, edge_notch_d + 2*eps, edge_notch_h + 2*eps], center=true);
}

// ---------------- Final ----------------
difference() {
  plate_solid();
  slots_cut();
  corner_recess_rings_cut();
  mid_side_notches_cut();
}

// Connected L/C bracket with clear end-plate slope and through hex hole
// Bounding box target: 55.44 x 31.55 x 37.52 mm (X x Y x Z)

$fn = 96;

// Bounding box
bbox_L = 55.44;
bbox_W = 31.55;
bbox_H = 37.52;

// Main members
beam_L = bbox_L;
beam_W = bbox_W;
beam_H = 10;

end_plate_t = 6;
end_plate_H = bbox_H;

leg_t = 6;
leg_H = 18;

// Hex hole (through beam thickness, along Z)
hex_AF = 10;
hex_axis_angle_deg = 0;
hex_center_x_from_left = 27.72;
hex_center_y_from_front = 15.775;
hex_clearance = 0.2;

// End-plate slope (top chamfer)
slope_drop = 8;
slope_run  = 12;

// Small edge chamfers on beam (optional)
beam_edge_chamfer = 1;

// Small cylindrical reliefs at junctions
relief_r = 2;
relief_depth = 1.5;

overlap = 0.5;

// Helpers
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for pointy-top hex when AF is across flats

module horizontal_beam() {
  translate([0, 0, -bbox_H/2 + beam_H/2])
    cube([beam_L, beam_W, beam_H], center=true);
}

module tall_vertical_end_plate() {
  translate([-beam_L/2 + end_plate_t/2, 0, -bbox_H/2 + end_plate_H/2])
    cube([end_plate_t, beam_W, end_plate_H], center=true);
}

module short_vertical_support_leg() {
  translate([beam_L/2 - leg_t/2, 0, -bbox_H/2 + leg_H/2])
    cube([leg_t, beam_W, leg_H], center=true);
}

module hex_hole_prism() {
  af = hex_AF + hex_clearance;
  R  = hex_R_from_AF(af);

  // Centered in XY, extruded through beam thickness in Z
  translate([
      -beam_L/2 + hex_center_x_from_left,
      -beam_W/2 + hex_center_y_from_front,
      -bbox_H/2 + beam_H/2
    ])
    rotate([0, 0, hex_axis_angle_deg])
      linear_extrude(height=beam_H + 2*overlap, center=true)
        polygon(points=[
          [ R, 0],
          [ R/2,  af/2],
          [-R/2,  af/2],
          [-R, 0],
          [-R/2, -af/2],
          [ R/2, -af/2]
        ]);
}

module slope_cut_wedge() {
  // Cut a wedge from the TOP of the tall end plate to create a visible sloped face.
  // Slope runs along +X (from left edge toward beam), dropping in Z by slope_drop over slope_run.
  ang = atan(slope_drop / slope_run);

  x_left = -beam_L/2;
  x_right = x_left + end_plate_t;
  z_top = -bbox_H/2 + end_plate_H;

  // Use a large cutter rotated about Y; positioned so it intersects the plate top.
  // Make it wide in Y and tall in Z to guarantee a clean cut.
  translate([x_right - slope_run/2, 0, z_top - slope_drop/2])
    rotate([0, -ang, 0])
      cube([slope_run + 4*overlap, beam_W + 4*overlap, slope_drop + end_plate_H + 4*overlap], center=true);
}

module beam_chamfer_wedge_top_front() {
  if (beam_edge_chamfer > 0)
    translate([0, beam_W/2 - beam_edge_chamfer/2, -bbox_H/2 + beam_H - beam_edge_chamfer/2])
      rotate([45, 0, 0])
        cube([beam_L + 4*overlap, beam_edge_chamfer, beam_edge_chamfer], center=true);
}

module beam_chamfer_wedge_top_back() {
  if (beam_edge_chamfer > 0)
    translate([0, -beam_W/2 + beam_edge_chamfer/2, -bbox_H/2 + beam_H - beam_edge_chamfer/2])
      rotate([-45, 0, 0])
        cube([beam_L + 4*overlap, beam_edge_chamfer, beam_edge_chamfer], center=true);
}

module alignment_relief_left() {
  // Relief at left plate/beam junction (cuts into beam near plate)
  translate([-beam_L/2 + end_plate_t + relief_depth/2, 0, -bbox_H/2 + beam_H/2])
    rotate([0, 90, 0])
      cylinder(r=relief_r, h=relief_depth + 2*overlap, center=true);
}

module alignment_relief_right() {
  // Relief at right leg/beam junction (cuts into beam near leg)
  translate([beam_L/2 - leg_t - relief_depth/2, 0, -bbox_H/2 + beam_H/2])
    rotate([0, 90, 0])
      cylinder(r=relief_r, h=relief_depth + 2*overlap, center=true);
}

module final_bracket() {
  difference() {
    union() {
      horizontal_beam();
      tall_vertical_end_plate();
      short_vertical_support_leg();
    }

    // Cuts
    slope_cut_wedge();
    beam_chamfer_wedge_top_front();
    beam_chamfer_wedge_top_back();
    alignment_relief_left();
    alignment_relief_right();
    hex_hole_prism();
  }
}

color("Silver") final_bracket();

// Rigid C-shaped / U-bracket with open rectangular throat and a CLEAR hex through-hole
// Bounding box target: 55.4 x 31.5 x 37.5 mm (L x W x H)

$fn = 96;

// -------------------- Parameters (mm) --------------------
bbox_L = 55.44;
bbox_W = 31.55;
bbox_H = 37.52;

wall_t        = 4.0;   // leg thickness along X
bar_thickness = 8.0;   // base bar thickness along Z

// Leg heights (asymmetric)
long_leg_H  = bbox_H;  // tall leg reaches full height
short_leg_H = 22.0;    // shorter leg

// Throat (open window) dimensions (void)
throat_L = 39.0;
throat_W = 23.0;

// Hex through-hole (through Z so hex is visible in TOP view)
hex_flat_to_flat         = 8.0;
hex_hole_offset_from_end = 10.0; // from left end along X
hex_hole_y_from_center   = 0.0;  // centered in width

// Place hole in the base bar so it is unmistakably present
hex_hole_z_from_bottom   = bar_thickness/2; // centered in bar thickness

// Chamfer/taper on outer end of tall leg (left end)
chamfer_len  = 3.0;   // along X
chamfer_drop = 1.5;   // along Z

// Robust boolean overlap
eps = 0.6;

// -------------------- Helpers --------------------
function hex_R_from_F(F) = F / sqrt(3); // circumradius for flat-to-flat F

module hex_prism_through_z(F, hZ) {
    // Hex centered at origin in XY, extruded along Z
    linear_extrude(height=hZ, center=true)
        polygon(points=[
            for (i=[0:5]) [
                hex_R_from_F(F) * cos(60*i),
                hex_R_from_F(F) * sin(60*i)
            ]
        ]);
}

// -------------------- Main solids --------------------
module long_bar() {
    // Base bar spans full length and width, thickness in Z, bottom at Z=0
    translate([0, 0, bar_thickness/2])
        cube([bbox_L, bbox_W, bar_thickness], center=true);
}

module leg_at_end(is_left=true, H=30) {
    // Vertical plate at an end, spanning full width in Y, thickness wall_t in X
    // Slight overlap into the bar for watertight union
    x = (is_left ? -bbox_L/2 + wall_t/2 : bbox_L/2 - wall_t/2);
    translate([x, 0, H/2])
        cube([wall_t + eps, bbox_W, H], center=true);
}

module u_bracket_solid() {
    union() {
        long_bar();
        leg_at_end(true,  long_leg_H);
        leg_at_end(false, short_leg_H);
    }
}

module throat_void() {
    // Remove a rectangular window above the bar, leaving end legs and open throat.
    // Keep a little clearance from the legs by using throat_L < (bbox_L - 2*wall_t).
    z_h = (bbox_H - bar_thickness) + 2*eps;
    translate([0, 0, bar_thickness + (bbox_H - bar_thickness)/2])
        cube([throat_L, throat_W, z_h], center=true);
}

module hex_hole() {
    // CLEAR hex through-hole through Z (visible in TOP view), located near left end.
    // Drill through the base bar thickness (plus eps) so it always cuts.
    x = -bbox_L/2 + hex_hole_offset_from_end;
    y = hex_hole_y_from_center;
    z = hex_hole_z_from_bottom;

    translate([x, y, z])
        hex_prism_through_z(hex_flat_to_flat, bar_thickness + 2*eps);
}

module long_leg_outer_chamfer() {
    // Chamfer at the OUTER top end of the tall (left) leg.
    // Cut a wedge near the leftmost face, sloping down toward +X.
    x_outer = -bbox_L/2;

    // Position cutter so it intersects the top of the long leg and the outer face.
    // Use generous size + eps to guarantee a clean cut.
    translate([x_outer + chamfer_len/2, 0, long_leg_H - chamfer_drop/2])
        rotate([0, 35, 0])
            cube([chamfer_len*2.4, bbox_W + 2*eps, chamfer_drop*3.4], center=true);
}

// -------------------- Final model --------------------
difference() {
    u_bracket_solid();
    throat_void();
    hex_hole();
    long_leg_outer_chamfer();
}

// Parameters
L = 54.99; //[27.5:110.0:0.01]
W = 16.58; //[8.29:33.16:0.01]
