    csk_cone([hex_axis_offset_L, 0, H/2 - (csk_depth + overlap)/2], [0, 0, 0]);
    csk_cone([hex_axis_offset_L, 0, -H/2 + (csk_depth + overlap)/2], [180, 0, 0]);
  }
}

module edge_fillets() {
