module bore_chamfer_bottom() {
    translate([0, 0, -H/2 + bore_chamfer/2])
        cylinder(h=bore_chamfer + overlap, r1=bore_d/2 + bore_chamfer, r2=bore_d/2, center=true);
}

module bore_cut() {
    union() {
        through_bore();
        bore_chamfer_top();
        bore_chamfer_bottom();
    }
}

// Final
difference() {
    outer_profile();
    bore_cut();
}

