W = 31.0;
T = 3.5;

// Rounded-rectangle main body
corner_r = 6.0;

// Stepped extension (narrower) on one end, ending in a U-notch
step_len   = 18.0;
step_width = 22.0;

// U-notch (open to the end)
notch_depth   = 10.0;
notch_width   = 12.0;
notch_inner_r = 3.0;

// Holes
grid_hole_d  = 5.0;
grid_pitch_x = 18.0;   // between the two columns
grid_pitch_y = 12.0;   // between rows
small_hole_d = 3.0;

// Placement
eps = 0.02;
cut_h = T + 2*eps;

// Helpers
module rounded_rect_2d(len, wid, r) {
  r2 = min(r, min(len, wid)/2);
  hull() {
    translate([ r2,      r2])      circle(r=r2);
    translate([len-r2,   r2])      circle(r=r2);
    translate([ r2,    wid-r2])    circle(r=r2);
    translate([len-r2, wid-r2])    circle(r=r2);
  }
}

module plate_outline_2d() {
  // Main rounded rectangle + stepped extension (connected)
  union() {
    // Main body spans x: [-L/2, +L/2]
    translate([-L/2, -W/2])
      rounded_rect_2d(L, W, corner_r);

    // Step extension on +X end, centered in Y
    translate([L/2 - eps, -step_width/2])
      square([step_len + eps, step_width], center=false);
  }
}

module u_notch_cut_2d() {
  // U-shaped notch open to the +X end of the step
  // Build as a rectangle open to the end plus a semicircular bottom.
  // Step end is at x = L/2 + step_len
  x_end = L/2 + step_len;
  x0 = x_end - notch_depth;

  union() {
    // Rectangular throat (open to end)
    translate([x0, -notch_width/2])
      square([notch_depth + eps, notch_width], center=false);

    // Rounded bottom of the U
    translate([x0 + notch_inner_r, 0])
      circle(r=notch_inner_r);
  }
}

module holes_cut_2d() {
  // Place 2x3 grid near the stepped/notched end (as in reference)
  // Keep it within the main body width and near +X.
  grid_center_x = L/2 - 14.0; // near the step shoulder
  grid_center_y = 0.0;

  // 2 columns (left/right), 3 rows (top/mid/bot)
  for (ix = [-0.5, 0.5], iy = [-1, 0, 1]) {
    translate([grid_center_x + ix*grid_pitch_x, grid_center_y + iy*grid_pitch_y])
      circle(d=grid_hole_d);
  }

  // Small hole near the rounded end (opposite side, near -X)
  small_hole_x = -L/2 + 18.0;
  small_hole_y = 0.0;
  translate([small_hole_x, small_hole_y])
    circle(d=small_hole_d);
}

module bracket() {
  difference() {
    linear_extrude(height=T, center=true)
      plate_outline_2d();

    // Notch cut
    translate([0,0,0])
      linear_extrude(height=cut_h, center=true)
        u_notch_cut_2d();

    // Through holes
    translate([0,0,0])
      linear_extrude(height=cut_h, center=true)
        holes_cut_2d();
  }
}

bracket();

// Thin mounting/adapter plate with central cutout, row windows, ring feature, and perimeter tabs/holes
// Bounding box target: 81.2 x 68.5 x 10.0 mm

$fn = 128;

// -------------------- Parameters --------------------
bbox_L = 81.15;
bbox_W = 68.5;
plate_T = 10;

outer_corner_R = 2;

frame_margin = 6;

central_cut_L = 55;
central_cut_W = 40;

// Prominent circular ring feature on one end (boss + through-hole)
ring_outer_D = 26;
ring_hole_D  = 14;

// Place ring so its outermost edge is flush with the outer right edge of the bbox
ring_center_x = bbox_L/2 - ring_outer_D/2;
ring_center_y = 0;

// Perimeter tabs (small outward pads) and fastener holes
tab_L = 8;
tab_W = 10;

fastener_hole_D = 3.2;
fastener_edge_offset = 4;

counterbore_D = 6.4;
counterbore_depth = 2.5;

// Row of small rectangular windows (arranged in a row)
window_count = 4;
window_L = 10;
window_W = 6;
window_gap = 4;

// Put window row in the top bar area (above central cutout)
window_row_y = central_cut_W/2 + frame_margin/2;

// Small overlap for robust booleans
overlap = 1;

// -------------------- Helpers --------------------
module rounded_rect_2d(L, W, R) {
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(L/2 - R), sy*(W/2 - R)]) circle(r=R);
  }
}

module outer_plate_2d() {
  rounded_rect_2d(bbox_L, bbox_W, outer_corner_R);
}

module ring_boss_2d() {
  // Full circular boss (ring outer profile)
  translate([ring_center_x, ring_center_y]) circle(d=ring_outer_D);
}

module base_outline_2d() {
  // Union of main plate outline + ring boss (connected solid)
  union() {
    outer_plate_2d();
    ring_boss_2d();
  }
}

module tab_2d_at(x, y) {
  translate([x, y]) square([tab_L, tab_W], center=true);
}

module tabs_2d() {
  // Tabs protruding outward from the main rectangle edges
  // Right side tabs (top/mid/bot)
  tab_2d_at( bbox_L/2 + tab_L/2 - 0.01,  bbox_W/2 - tab_W/2);
  tab_2d_at( bbox_L/2 + tab_L/2 - 0.01,  0);
  tab_2d_at( bbox_L/2 + tab_L/2 - 0.01, -bbox_W/2 + tab_W/2);

  // Left side tabs (top/mid/bot)
  tab_2d_at(-bbox_L/2 - tab_L/2 + 0.01,  bbox_W/2 - tab_W/2);
  tab_2d_at(-bbox_L/2 - tab_L/2 + 0.01,  0);
  tab_2d_at(-bbox_L/2 - tab_L/2 + 0.01, -bbox_W/2 + tab_W/2);

  // Top-center tab
  tab_2d_at(0, bbox_W/2 + tab_W/2 - 0.01);

  // Bottom-center tab
  tab_2d_at(0, -bbox_W/2 - tab_W/2 + 0.01);
}

module solid_2d() {
  union() {
    base_outline_2d();
    tabs_2d();
  }
}

module central_cutout_2d() {
  // Main rectangular clearance
  square([central_cut_L, central_cut_W], center=true);
}

module window_row_cutouts_2d() {
  // Several smaller rectangular windows arranged in a row
  total_L = window_count*window_L + (window_count-1)*window_gap;
  x0 = -total_L/2 + window_L/2;

  for (i = [0:window_count-1])
    translate([x0 + i*(window_L + window_gap), window_row_y])
      square([window_L, window_W], center=true);
}

module ring_through_hole_2d() {
  // Through-hole inside the ring boss
  translate([ring_center_x, ring_center_y]) circle(d=ring_hole_D);
}

module fastener_holes_2d() {
  // Holes centered on tabs, offset inward from the outermost tab edge by fastener_edge_offset
  // Right side (3)
  for (yy = [bbox_W/2 - tab_W/2, 0, -bbox_W/2 + tab_W/2])
    translate([bbox_L/2 + tab_L - fastener_edge_offset, yy]) circle(d=fastener_hole_D);

  // Left side (3)
  for (yy = [bbox_W/2 - tab_W/2, 0, -bbox_W/2 + tab_W/2])
    translate([-bbox_L/2 - tab_L + fastener_edge_offset, yy]) circle(d=fastener_hole_D);

  // Top center (1)
  translate([0, bbox_W/2 + tab_W - fastener_edge_offset]) circle(d=fastener_hole_D);

  // Bottom center (1)
  translate([0, -bbox_W/2 - tab_W + fastener_edge_offset]) circle(d=fastener_hole_D);
}

module counterbores_3d() {
  // Counterbores on the "top" face only
  zc = plate_T/2 - (counterbore_depth + overlap)/2;

  // Right side (3)
  for (yy = [bbox_W/2 - tab_W/2, 0, -bbox_W/2 + tab_W/2])
    translate([bbox_L/2 + tab_L - fastener_edge_offset, yy, zc])
      cylinder(d=counterbore_D, h=counterbore_depth + overlap, center=true);

  // Left side (3)
  for (yy = [bbox_W/2 - tab_W/2, 0, -bbox_W/2 + tab_W/2])
    translate([-bbox_L/2 - tab_L + fastener_edge_offset, yy, zc])
      cylinder(d=counterbore_D, h=counterbore_depth + overlap, center=true);

  // Top center (1)
  translate([0, bbox_W/2 + tab_W - fastener_edge_offset, zc])
    cylinder(d=counterbore_D, h=counterbore_depth + overlap, center=true);

  // Bottom center (1)
  translate([0, -bbox_W/2 - tab_W + fastener_edge_offset, zc])
    cylinder(d=counterbore_D, h=counterbore_depth + overlap, center=true);
}

// -------------------- Final Model --------------------
module plate_solid_3d() {
  linear_extrude(height=plate_T, center=true)
    solid_2d();
}

module all_cutouts_3d() {
  union() {
    // Through cutouts
    linear_extrude(height=plate_T + 2*overlap, center=true) {
      central_cutout_2d();
      window_row_cutouts_2d();
      ring_through_hole_2d();
      fastener_holes_2d();
    }

    // Counterbores (partial depth)
    counterbores_3d();
  }
}

difference() {
  plate_solid_3d();
  all_cutouts_3d();
}

// Thin constant-thickness bracket-like part:
// central rectangular pad + two long arms angled (shallow V/boomerang in side view)
// with large blended/concave-looking transitions. No holes/cutouts.
// Target bbox: 11.0 x 43.9 x 10.9 mm (X x Y x Z)

$fn = 96;

// ---------------- Parameters ----------------
bbox_X = 10.97;   // overall width (X)
bbox_Y = 43.93;   // overall length (Y)
bbox_Z = 10.92;   // overall height (Z) due to arm angle

thk    = 1.20;    // constant sheet thickness (extrusion height)

pad_L  = 12.0;    // central pad length along Y (distinct pad)
pad_W  = bbox_X;  // pad width along X

arm_angle_deg = 18.0;  // arm tilt about X (creates shallow V in side view)
end_R   = 5.0;         // rounded arm ends in plan

// Overlap for robust manifold unions (1–2mm)
overlap = 1.2;

// Derived arm length so overall Y matches bbox_Y
arm_L = (bbox_Y - pad_L)/2;

// Blend length near the root (make it large/visible)
blend_L = min(12, arm_L);

// ---------------- Helpers ----------------
module rrect2d(w, l, r) {
    r2 = min(r, w/2, l/2);
    hull() {
        for (sx=[-1,1], sy=[-1,1])
            translate([sx*(w/2 - r2), sy*(l/2 - r2)]) circle(r=r2);
    }
}

// 3D strap with angled arms and large blended transitions
module strap3d() {
    union() {
        // Central pad (flat, distinct)
        linear_extrude(height=thk, center=true, convexity=10)
            square([pad_W, pad_L], center=true);

        // Arms: place their root edge at the pad edge (with overlap), then rotate about X.
        // Use center=true extrusions; translate in Y by half-length so the root aligns.
        for (s=[-1,1]) {
            // Root alignment:
            // pad edge at y = s*pad_L/2
            // arm local root edge at y = -s*arm_L/2 (because arm is centered)
            // so translate by y = s*(pad_L/2 - overlap) + s*(arm_L/2)
            translate([0, s*(pad_L/2 - overlap + arm_L/2), 0])
                rotate([s*arm_angle_deg, 0, 0])
                    linear_extrude(height=thk, center=true, convexity=10)
                        rrect2d(pad_W, arm_L, end_R);

            // Large blended/concave-looking transition:
            // Hull between a wider pad "tab" and a short rotated arm segment near the root.
            hull() {
                // Pad-side tab (flat) slightly longer to read as a filleted/concave blend region
                linear_extrude(height=thk, center=true, convexity=10)
                    translate([0, s*(pad_L/2 - overlap/2)])
                        square([pad_W, blend_L], center=true);

                // Arm-side short segment near root:
                // Place a short segment so its root overlaps the pad edge region.
                // Segment length = blend_L; align its root edge to pad edge with overlap.
                translate([0, s*(pad_L/2 - overlap + blend_L/2), 0])
                    rotate([s*arm_angle_deg, 0, 0])
                        linear_extrude(height=thk, center=true, convexity=10)
                            rrect2d(pad_W, blend_L + overlap, end_R);
            }
        }
    }
}

// Clip to requested bounding box while keeping one connected solid
module bbox_clip() { cube([bbox_X, bbox_Y, bbox_Z], center=true); }

// ---------------- Final ----------------
intersection() {
    strap3d();
    bbox_clip();
}

// Small mounting clip/bracket (single connected solid)
// Target bounding box (approx): X=5.4, Y=1.4, Z=9.0
// Elongated along Z

$fn = 72;

// ---------------- Parameters ----------------
bbox_X = 5.40;   // X width
bbox_Y = 1.40;   // Y thickness
bbox_Z = 9.00;   // Z length

// Base plate
base_W = bbox_X;         // X
base_T = 0.70;           // Y
base_L = bbox_Z;         // Z
base_corner_R = 0.55;

// Central raised spine (continuous along most of base)
spine_W = 1.25;          // X
spine_H = 0.40;          // Y
spine_L = base_L * 0.82; // Z

// Cradle / hook (forward-projecting along +Z)
cradle_opening_W = 1.70; // X span of hook seat (between tips)
cradle_inner_R   = 0.75; // inner seat radius (rod/cable radius)
cradle_arm_thk   = 0.55; // arm thickness (radial thickness)
cradle_proj      = 2.05; // how far beyond base front edge the hook reaches (+Z)

// Nubs at hook tips
nub_D = 0.70;
nub_L = 0.55;

// Reliefs
void_depth = 0.30;
void_R = 0.55;

// Overlap for robust unions (small model: keep modest)
overlap = 0.20;

// ---------------- Helpers ----------------
module rounded_rect_prism(size=[10,1,10], r=1, center=true) {
  // size = [X,Y,Z]
  minkowski() {
    cube([max(0.01, size[0]-2*r), max(0.01, size[1]-2*r), max(0.01, size[2]-2*r)], center=center);
    sphere(r=r);
  }
}

// ---------------- Base ----------------
module base_plate() {
  rounded_rect_prism([base_W, base_T, base_L], r=base_corner_R, center=true);
}

module base_internal_relief_void() {
  // shallow underside relief, stays inside base
  translate([0, -base_T/2 + void_depth/2 + overlap/2, 0])
    rounded_rect_prism([base_W - 2*void_R, void_depth + overlap, base_L - 2*void_R], r=void_R, center=true);
}

// ---------------- Spine ----------------
module central_spine() {
  translate([0, base_T/2 + spine_H/2 - overlap/2, 0])
    rounded_rect_prism([spine_W, spine_H + overlap, spine_L], r=min(0.25, spine_W/2-0.01), center=true);
}

// ---------------- Cradle (U-shaped hook) ----------------
module cradle_hook_solid() {
  // U-shaped forward-projecting cradle: partial torus segment extruded along X.
  // Open toward +Y (up), and only forward-facing (toward +Z).
  arm_r = cradle_arm_thk/2;
  Rmid  = cradle_inner_R + arm_r;

  // Place hook so it is clearly in front of the base and connected via a web.
  // Ensure forward reach: outermost Z approx = base_L/2 + cradle_proj
  y0 = base_T/2 + spine_H - overlap/2;
  z0 = (base_L/2 + cradle_proj) - (Rmid + arm_r);  // center of arc

  translate([0, y0, z0])
  rotate([0,90,0])  // extrude along X
  intersection() {
    // Ring (tube) extruded across full width; later clipped to opening width.
    linear_extrude(height=base_W + 2*overlap, center=true, convexity=10)
      difference() {
        circle(r=Rmid + arm_r);
        circle(r=Rmid - arm_r);
      }

    // Keep only the lower half of the ring (so it opens upward toward +Y).
    // In this local frame, "up" is +Y of the 2D profile.
    translate([0, -(Rmid + arm_r)*0.60, 0])
      cube([base_W + 4*overlap, 2*(Rmid + arm_r) + 4*overlap, 2*(Rmid + arm_r) + 4*overlap], center=true);

    // Keep only the forward-facing portion (no wrap behind the base).
    // Local +Z corresponds to global +Z after the rotate.
    translate([0, 0, +(Rmid + arm_r)*0.35])
      cube([base_W + 4*overlap, 3*(Rmid + arm_r) + 4*overlap, 1.70*(Rmid + arm_r) + 4*overlap], center=true);

    // Limit hook to opening width in X (so it reads as a cradle, not a full-width ring).
    cube([cradle_opening_W + 2*overlap, 5*(Rmid + arm_r) + 4*overlap, 5*(Rmid + arm_r) + 4*overlap], center=true);
  }
}

module cradle_end_nubs() {
  // Nubs at the two hook tips (left/right in X), positioned to intersect the hook solid.
  arm_r = cradle_arm_thk/2;
  Rmid  = cradle_inner_R + arm_r;

  y0 = base_T/2 + spine_H - overlap/2;
  z0 = (base_L/2 + cradle_proj) - (Rmid + arm_r);

  // Put nubs at the forward/lower tip region of the kept arc.
  // Ensure they intersect the hook and remain within overall X.
  x_tip = cradle_opening_W/2;
  y_tip = y0 - 0.05;
  z_tip = z0 + (Rmid + arm_r) * 0.70;

  union() {
    translate([ x_tip, y_tip, z_tip])
      rotate([90,0,0]) cylinder(r=nub_D/2, h=nub_L, center=true);
    translate([-x_tip, y_tip, z_tip])
      rotate([90,0,0]) cylinder(r=nub_D/2, h=nub_L, center=true);
  }
}

module cradle_inner_relief_void() {
  // Hollow out the seat (cylindrical) to make a clear cradle for a rod/cable.
  arm_r = cradle_arm_thk/2;
  Rmid  = cradle_inner_R + arm_r;

  y0 = base_T/2 + spine_H - overlap/2;
  z0 = (base_L/2 + cradle_proj) - (Rmid + arm_r);

  translate([0, y0, z0])
    rotate([0,90,0])
      cylinder(r=cradle_inner_R, h=cradle_opening_W + 2*overlap, center=true);
}

module cradle_connection_web() {
  // Strong, obvious connection between spine/front of base and the hook.
  // Web overlaps both the spine and the hook base region.
  arm_r = cradle_arm_thk/2;
  Rmid  = cradle_inner_R + arm_r;

  // Hook center
  y_hook = base_T/2 + spine_H - overlap/2;
  z_hook = (base_L/2 + cradle_proj) - (Rmid + arm_r);

  // Start near the base front edge (slightly inside to guarantee overlap)
  z_base_front = base_L/2 - base_corner_R*0.40;

  // End slightly behind hook center so it intersects the hook body
  z_web_end = z_hook + (Rmid + arm_r)*0.05;

  web_L  = (z_web_end - z_base_front) + 2*overlap;
  web_Zc = (z_base_front + z_web_end)/2;

  // Web height: reaches up to hook centerline region
  web_H = spine_H + 0.35;

  translate([0, base_T/2 + web_H/2 - overlap/2, web_Zc])
    rounded_rect_prism([spine_W + 0.90, web_H + overlap, web_L], r=0.20, center=true);
}

// ---------------- Assembly ----------------
module complete_model() {
  difference() {
    union() {
      base_plate();
      central_spine();

      // Forward-projecting open cradle + nubs + connecting web
      cradle_hook_solid();
      cradle_end_nubs();
      cradle_connection_web();
    }

    // Voids
    base_internal_relief_void();
    cradle_inner_relief_void();
  }
}

complete_model();

// Curved C-shaped clamp/brace segment (structurally corrected)
// Target bounding box: 3.0 x 1.2 x 9.0 mm (X x Y x Z), elongated along Z

// ---------------- Parameters ----------------
bbox_L = 9.0;   // Z length
bbox_W = 3.0;   // X width
bbox_H = 1.2;   // Y thickness

// Ring radii (must fit within bbox_W/2 = 1.5)
arc_outer_R = 1.5;
arc_inner_R = 1.05;

// Arc span (C-shape)
arc_angle_deg = 220.0;

// End tabs (squared-off, slightly thickened)
tab_len = 0.7;          // along Z
tab_W = 3.0;            // along X
tab_H = 1.2;            // along Y
tab_thicken = 0.15;     // extra thickness on +Y face

// Faceting (outer surface)
facet_count = 10;

// Overlap for robust unions/differences (kept small at this scale)
overlap = 0.25;

// Optional small relief notches (kept on tabs only)
notch_W = 0.35;         // along X
notch_L = 0.25;         // along Z
notch_H = 0.5;          // along Y

// ---------------- Derived ----------------
mid_R   = (arc_outer_R + arc_inner_R) / 2;
rad_thk = (arc_outer_R - arc_inner_R);
arc_start = -arc_angle_deg/2;

// ---------------- Helpers ----------------
module arc_ring_segment() {
    // Build a partial ring in the XY plane (rotate_extrude about Z),
    // then rotate it so the arc runs along Z (elongated axis).
    rotate([90,0,0])  // map original Y -> Z so length becomes along Z
        rotate([0,0,arc_start])
            rotate_extrude(angle=arc_angle_deg, $fn=facet_count)
                translate([mid_R, 0, 0])
                    square([rad_thk, bbox_H], center=true);
}

module inner_channel_cut() {
    // Subtract a concave inner channel (cylindrical-like) along the same arc.
    rotate([90,0,0])
        rotate([0,0,arc_start])
            rotate_extrude(angle=arc_angle_deg, $fn=max(64, facet_count*8))
                translate([arc_inner_R, 0, 0])
                    square([2*rad_thk + 2*overlap, bbox_H + 2*overlap], center=true);
}

module end_tabs() {
    // Place tabs at the two arc ends using the actual end positions of the rotated arc.
    // After rotate([90,0,0]), a point (x,y,0) becomes (x,0,y), so Z comes from original Y.
    a1 = arc_start;
    a2 = arc_start + arc_angle_deg;

    // Endpoints of the mid-radius centerline in original XY:
    // (x,y) = (mid_R*cos(a), mid_R*sin(a))
    // After rotation, Z = y.
    z1 = mid_R * sin(a1);
    z2 = mid_R * sin(a2);

    // Ensure tabs overlap into the arc body for connectivity
    tab_len_eff = tab_len + 2*overlap;

    union() {
        for (z = [z1, z2]) {
            // Base tab (squared-off)
            translate([0, 0, z])
                cube([tab_W, tab_H, tab_len_eff], center=true);

            // Thickening pad on +Y face
            translate([0, bbox_H/2 - tab_thicken/2, z])
                cube([tab_W, tab_thicken, tab_len_eff], center=true);
        }
    }
}

module tab_notches_cut() {
    // Cut notches only where tabs exist (at tab Z centers).
    a1 = arc_start;
    a2 = arc_start + arc_angle_deg;

    z1 = mid_R * sin(a1);
    z2 = mid_R * sin(a2);

    x1 = -bbox_W/2 + notch_W/2;
    x2 =  bbox_W/2 - notch_W/2;

    union() {
        for (z = [z1, z2]) {
            for (x = [x1, x2]) {
                translate([x, 0, z])
                    cube([notch_W, notch_H, notch_L], center=true);
            }
        }
    }
}

module trim_to_bbox() {
    cube([bbox_W, bbox_H, bbox_L], center=true);
}

// ---------------- Build ----------------
module clamp_segment() {
    difference() {
        // Keep everything connected as one solid, then trim to bbox.
        intersection() {
