// Dominant long bar (spans X)
bar_len = bbox_x;
bar_w   = 7.0;

// Fewer distinct spokes at varied angles (not evenly spaced teeth)
spoke_angles_deg = [25, 55, 90, 125, 155, 205, 235];  // varied, not uniform
