module prong_tip_rounders() {
  // Left end (at x = -L/2)
  for (sy = [-1, 1], sz = [-1, 1])
    translate([-(L/2) + tip_round, sy*(slot_width/2), sz*(D/2)])
      sphere(r=tip_round);

  // Right end (at x = +L/2)
  for (sy = [-1, 1], sz = [-1, 1])
    translate([(L/2) - tip_round, sy*(slot_width/2), sz*(D/2)])
      sphere(r=tip_round);
