module final_model() {
  difference() {
    union() {
      main_body();
      end_taper_left();
      end_taper_right();
      end_stub_left();
      end_stub_right();
    }
    // Cut U-slots
    slot_cutter_left();
    slot_cutter_right();

    // Round slot roots
    slot_root_round_left();
    slot_root_round_right();

    // Round prong tips (small chamfer/round impression)
    prong_tip_rounders();
