// Diamond ring (loop) in XZ plane, extruded along Y
module diamond_loop() {
  translate([0, 0, diamond_center_z])
    linear_extrude(height=thk, center=true)
      difference() {
        diamond_2d(diamond_W, diamond_H);
        offset(delta=-brace_W) diamond_2d(diamond_W, diamond_H);
      }
