          polygon(points=[[0, diamond_H/2 - brace_W], [0, -diamond_H/2 + brace_W]]);
        // horizontal brace
        offset(delta=rib_w/2)
          polygon(points=[[ diamond_W/2 - brace_W, 0], [-diamond_W/2 + brace_W, 0]]);
