  for (i = [0:spine_eyelet_count-2]) {
    zmid = -spine_L/2 + spine_eyelet_offset_from_end + (i+0.5)*spine_eyelet_spacing;
    translate([0, 0, zmid])
      cube([lighten_slot_W, thk + 2*overlap, lighten_slot_L], center=true);
  }
}

