difference() {
  union() {
    // central vertical spine
    spine_box();

    // boss/cap at one end of spine
    boss_cap();

    // diamond loop at top end of spine
    diamond_loop();
    corner_eyelets();
    junction_webs();
    diamond_braces();

    // multiple eyelets along spine
    spine_eyelets();
  }

  // lightening cutouts
  spine_lightening_slots();
}

