// Faceted 5-point star polyhedron (single connected solid)
// Target bounding box: 54.41 x 57.06 x 89.95 mm

// ---------------- Parameters ----------------
bbox_x = 54.41;
bbox_y = 57.06;
bbox_z = 89.95;

num_points = 5;

hub_radius = 12.0;
hub_height = 22.0;

lobe_length = 45.0;
lobe_base_width = 22.0;
lobe_thickness = 18.0;

lobe_twist_deg = 0.0;
overlap = 1.0;

base_trim_height = 2.0;

// Keep solid (no internal cavity subtraction)
make_internal_cavity = false;
cavity_scale_xy = 0.62;
cavity_scale_z  = 0.62;
cavity_z_offset = 6.0;

// ---------------- Helpers ----------------
function clamp(x,a,b) = min(max(x,a),b);

// A faceted "pyramidal lobe" built as a polyhedron (planar triangular faces)
module lobe_poly(lobe_len, base_w, base_t, z0, z1) {
    // Base rectangle at z0, apex at z1
    // Local coordinates: +X points outward from hub
    x0 = 0;
    x1 = base_t;
    y0 = -base_w/2;
    y1 =  base_w/2;

    apex = [lobe_len, 0, z1];

    p0 = [x0, y0, z0];
    p1 = [x1, y0, z0];
    p2 = [x1, y1, z0];
    p3 = [x0, y1, z0];

    polyhedron(
        points = [p0,p1,p2,p3,apex],
        faces = [
            [0,1,2,3],   // base (internal-ish; helps keep manifold)
            [0,1,4],
            [1,2,4],
            [2,3,4],
            [3,0,4]
        ],
        convexity = 10
    );
}

// Central stellated hub: a faceted bipyramid-like core to visually merge lobes
module central_core() {
    // Faceted core via hull of two short cylinders (gives planar-ish facets with low $fn)
    core_r = hub_radius;
    core_h = hub_height;

    hull() {
        translate([0,0,-core_h/2 + overlap])
            cylinder(r=core_r, h=overlap*2, center=true, $fn=10);
        translate([0,0, core_h/2 - overlap])
            cylinder(r=core_r*0.85, h=overlap*2, center=true, $fn=10);
    }
}

// One lobe positioned so its root overlaps into the hub (guaranteed connectivity)
module lobe_at(angle) {
    // Root plane slightly inside hub to ensure union connectivity
    root_x = hub_radius - overlap;                 // overlaps INTO hub
    z0 = -hub_height/2 + overlap;                  // start near hub bottom
    z1 =  bbox_z/2 - overlap;                      // apex near top

    rotate([0,0,angle + lobe_twist_deg])
        translate([root_x, 0, 0])
            lobe_poly(
                lobe_len = lobe_length + overlap,  // extra to keep tip sharp after scaling
                base_w   = lobe_base_width,
                base_t   = lobe_thickness,
                z0       = z0,
                z1       = z1
            );
}

// Optional internal cavity (disabled by default to keep "no openings" solid)
module internal_cavity() {
    translate([0,0,-hub_height/2 + cavity_z_offset])
        sphere(r = hub_radius + lobe_length*0.55, $fn=48);
}

// Small base trim to flatten bottom slightly (kept minimal)
module base_trim() {
    translate([0,0,-bbox_z/2 + base_trim_height/2])
        cube([2*(hub_radius + lobe_length) + 4, 2*(hub_radius + lobe_length) + 4, base_trim_height], center=true);
}

// ---------------- Model ----------------
module star_solid() {
    union() {
        central_core();
        for (i=[0:num_points-1])
            lobe_at(i*360/num_points);
    }
}

module final_model() {
    difference() {
        star_solid();

        if (make_internal_cavity)
            scale([cavity_scale_xy, cavity_scale_xy, cavity_scale_z])
                internal_cavity();

        // Keep a tiny flat so it stands; does not create openings
        base_trim();
    }
}

// ---------------- Scale to exact bounding box ----------------
// Build at nominal size then scale to target bbox.
// Nominal XY radius approx: hub_radius + lobe_length
nom_xy = 2*(hub_radius + lobe_length);
nom_z  = bbox_z;

sx = bbox_x / nom_xy;
sy = bbox_y / nom_xy;
sz = bbox_z / nom_z;

scale([sx, sy, sz])
    final_model();

// Symmetric prismatic connector/block
// Bounding box: 14.0 x 9.0 x 3.6 mm  (X x Y x Z)

L = 14.0;
W = 9.0;
T = 3.6;

// End masses and central web (H-profile in front/back)
end_L = 4.5;                 // length of each end mass along X
web_L = L - 2*end_L;          // central span along X
web_W = 3.6;                  // web width along Y

// Midspan relief notches on top and bottom edges (in Y), through full thickness (Z)
notch_L = 5.0;                // notch length along X
notch_W = 2.0;                // notch depth from edge along Y

eps = 0.02;                   // small overlap to avoid coplanar artifacts

module main_prismatic_body() {
    union() {
        // Central web
        cube([web_L, web_W, T], center=true);

        // End masses (connected to web with slight overlap)
        translate([-(web_L/2 + end_L/2 - eps), 0, 0])
            cube([end_L, W, T], center=true);

        translate([(web_L/2 + end_L/2 - eps), 0, 0])
            cube([end_L, W, T], center=true);
    }
}

module relief_notches() {
    // Cut rectangular notches from the top and bottom edges in Y,
    // through the full thickness in Z to match the H-profile views.
    union() {
        // Top edge notch (+Y)
        translate([0, (W/2 - notch_W/2), 0])
            cube([notch_L, notch_W + 2*eps, T + 2*eps], center=true);

        // Bottom edge notch (-Y)
        translate([0, -(W/2 - notch_W/2), 0])
            cube([notch_L, notch_W + 2*eps, T + 2*eps], center=true);
    }
}

difference() {
    main_prismatic_body();
    relief_notches();
}

// Compact housing with neck+tab (through-hole), side latch boss, and opposite-face recess
// Target bounding box: 1.4 x 1.0 x 2.6 mm  (X x Y x Z)

$fn = 64;

// --- Bounding box (overall) ---
bbox_X = 1.4;
bbox_Y = 1.0;
bbox_Z = 2.6;

// --- Main housing (rounded-rect) ---
housing_X = 1.00;                 // along X
housing_Y = bbox_Y;               // along Y
housing_Z = bbox_Z;               // along Z
housing_r = 0.18;                 // corner radius in XY

// --- Neck + tab (handle) on +X side ---
neck_X = 0.18;
neck_Y = 0.42;
neck_Z = bbox_Z;

tab_X  = bbox_X - housing_X - neck_X;   // ensures overall X matches bbox_X
tab_Y  = 0.70;
tab_Z  = bbox_Z;

hole_d = 0.28;
hole_from_tab_end = 0.20;          // from +X end of tab to hole center

// --- Side latch boss on +Y face (protruding) ---
latch_X = 0.30;
latch_Y = 0.18;
latch_Z = 0.35;
latch_from_housing_negX = 0.55;    // measured from housing -X end toward +X

// Make latch more "latch-like" with a small step/hook on its outer end
hook_X = 0.14;
hook_Y = 0.10;
hook_Z = 0.18;

// --- Recess notch on -Y face (shallow relief) ---
recess_X = 0.55;
recess_Y_depth = 0.14;             // shallow bite into -Y face
recess_Z = 0.55;
recess_from_housing_negX = 0.55;   // measured from housing -X end toward +X
recess_z_from_top = 0.35;          // closer to top so it reads in ortho views

// Small overlap to guarantee watertight unions/differences
eps = 0.02;

// ---------- Helpers ----------
module rounded_rect_prism_xy(size=[1,1,1], r=0.1, center=true) {
    rr = min(r, min(size[0], size[1]) / 2 - 1e-6);
    minkowski() {
        cube([size[0] - 2*rr, size[1] - 2*rr, size[2]], center=center);
        cylinder(r=rr, h=0.001, center=true);
    }
}

module housing_main() {
    rounded_rect_prism_xy([housing_X, housing_Y, housing_Z], housing_r, center=true);
}

module neck_block() {
    // Connected to housing on +X side with slight overlap
    translate([housing_X/2 + neck_X/2 - eps, 0, 0])
        cube([neck_X + 2*eps, neck_Y, neck_Z], center=true);
}

module tab_block() {
    // Connected to neck on +X side with slight overlap
    translate([housing_X/2 + neck_X + tab_X/2 - eps, 0, 0])
        rounded_rect_prism_xy(
            [tab_X + 2*eps, tab_Y, tab_Z],
            r=min(0.12, tab_Y/2 - 1e-6),
            center=true
        );
}

module hole_cut() {
    // Through-hole along Z, centered in Y, positioned from +X end of tab
    x_end  = housing_X/2 + neck_X + tab_X;     // +X end of tab (relative to origin)
    x_hole = x_end - hole_from_tab_end;
    translate([x_hole, 0, 0])
        cylinder(d=hole_d, h=bbox_Z + 2, center=true);
}

module latch_boss() {
    // Protrudes from +Y face of housing; positioned along X from housing -X end
    x0 = -housing_X/2 + latch_from_housing_negX;

    union() {
        // main boss (overlaps into housing slightly for solid connection)
        translate([x0, housing_Y/2 + latch_Y/2 - eps, 0])
            cube([latch_X, latch_Y + 2*eps, latch_Z], center=true);

        // small "hook/step" on the outer (+Y) end to read as a latch
        // placed on the boss' outer face, slightly toward +X and +Z
        translate([
            x0 + (latch_X/2 - hook_X/2) - eps,
            housing_Y/2 + latch_Y - hook_Y/2 - eps,
            (latch_Z/2 - hook_Z/2) - eps
        ])
            cube([hook_X, hook_Y + 2*eps, hook_Z], center=true);
    }
}

module recess_cut() {
    // Shallow recess into -Y face of housing (not through), clearly visible:
    // - anchored to the -Y face
    // - shifted upward in Z
    x0 = -housing_X/2 + recess_from_housing_negX;

    // Center the recess near the top (+Z) while staying inside the housing
    z0 = housing_Z/2 - recess_z_from_top - recess_Z/2;
    z0_clamped = max(-housing_Z/2 + recess_Z/2 + eps, min(housing_Z/2 - recess_Z/2 - eps, z0));

    // Place cutter so it bites into the -Y face by recess_Y_depth
    // Center of cutter is inside the housing by half the depth.
    y0 = -housing_Y/2 + recess_Y_depth/2 + eps;

    translate([x0, y0, z0_clamped])
        cube([recess_X, recess_Y_depth + 2*eps, recess_Z], center=true);
}

// ---------- Final solid ----------
difference() {
    union() {
        housing_main();
        neck_block();
        tab_block();
        latch_boss();
    }
    hole_cut();
    recess_cut();
}

