// Thick C-shaped / U-channel bracket with offset lug/stop
// Bounding box target: 31.8 x 31.8 x 15.8 mm

$fn = 64;
eps = 0.02;

// Overall bounds (X, Y, Z)
L = 31.8;
W = 31.8;
T = 15.8;

// U-channel geometry (open to -Y, web remains on +Y, jaws are top/bottom in Z)
jaw_T = 2.9;           // thickness of top and bottom jaws (Z)
web_W = 6.0;           // thickness of side web that remains on +Y side (Y)

// Internal cavity (rectangular cutout that OPENS to -Y to form a true C/U channel)
cut_L = 24.0;          // cavity length (X)
relief_r = 1.2;        // optional internal corner relief

// Lug/stop (protrudes from -Y face, offset in X)
lug_L = 6.0;
lug_W = 3.0;           // protrusion outward (Y)
lug_T = 4.0;
lug_offset_from_edge = 2.0;

// Derived
inner_Z   = T - 2*jaw_T;                 // open height between jaws
cut_T_eff = inner_Z + 2*eps;             // ensure clean boolean
cut_L_eff = min(cut_L, L - 2*eps);       // keep within outer

// Cavity placement: open to -Y (flush with -Y outer face), leave web on +Y
cut_y_min    = -W/2 - eps;               // slightly beyond -Y face to guarantee opening
cut_y_max    =  W/2 - web_W;             // stop before +Y face to leave web
cut_y_center = (cut_y_min + cut_y_max)/2;
cut_y_size   = (cut_y_max - cut_y_min);

// Cavity placement in Z: remove only between jaws (leave top/bottom jaws intact)
cut_z_center = 0;                         // centered between jaws
cut_z_size   = inner_Z + 2*eps;

// Optional: through holes in the cavity floor/plate (as seen in top view)
hole_r = 1.6;
hole_x_off = 8.5;

module bracket_body() {
    difference() {
        // Outer block
        cube([L, W, T], center=true);

        // Main cavity: removes material between jaws AND opens to -Y, leaving +Y web
        translate([0, cut_y_center, cut_z_center])
            cube([cut_L_eff, cut_y_size, cut_z_size], center=true);

        // Internal corner reliefs near the web-side corners (kept subtle)
        for (sx = [-1, 1]) {
            translate([
                sx*(cut_L_eff/2 - relief_r),
                cut_y_max - relief_r,
                cut_z_center
            ])
                rotate([90, 0, 0])
                    cylinder(r=relief_r, h=cut_y_size + 2*eps, center=true);
        }

        // Two through holes (Z direction), positioned within the cavity region
        for (sx = [-1, 1]) {
            translate([sx*hole_x_off, 0, 0])
                cylinder(r=hole_r, h=T + 2*eps, center=true);
        }
    }
}

module lug_stop() {
    // Offset in X from -X edge
    lug_x = -L/2 + lug_offset_from_edge + lug_L/2;

    // Attach to -Y face with overlap into the body for a single solid
    overlap_y = 1.5; // 1–2mm overlap for robust union
    // Body -Y face is at -W/2. Lug extends outward by lug_W and overlaps inward by overlap_y.
    lug_y = -W/2 - lug_W/2 + overlap_y/2;

    // Place near top surface (still within overall T)
    lug_z = T/2 - lug_T/2;

    translate([lug_x, lug_y, lug_z])
        cube([lug_L, lug_W + overlap_y, lug_T], center=true);
}

union() {
    bracket_body();
    lug_stop();
}

// Blocky C-shaped bracket/frame with stepped outer perimeter and inner step transitions
// Bounding box: 31.8 x 31.8 x 15.8 mm

// Parameters
bbox_x = 31.8;
bbox_y = 31.8;
bbox_z = 15.8;

frame_thk_z = bbox_z;

outer_step_depth = 2.0;
outer_step_margin = 3.0;

opening_x = 20.0;
opening_y = 20.0;

inner_step_depth = 1.5;
inner_step_width = 1.5;

c_gap_w = 8.0;

boss_w = 6.0;
boss_h = 6.0;
boss_z = bbox_z;
boss_inset = 0.0;

overlap = 0.6;

chamfer = 0.8;

nub_d = 2.0;
nub_h = 1.2;

relief_d = 3.0;
relief_depth = 1.0;

// Helpers
module box(sz, pos=[0,0,0]) { translate(pos) cube(sz, center=true); }
module cyl(r,h,pos=[0,0,0]) { translate(pos) cylinder(r=r, h=h, center=true, $fn=48); }

// Base solids
module outer_frame_plate() {
  box([bbox_x, bbox_y, frame_thk_z]);
}

// Outer stepped perimeter (a shallow "ring" on the top face)
module outer_perimeter_step_ring() {
  difference() {
    // slightly oversized in Z to avoid coplanar artifacts
    box([bbox_x, bbox_y, outer_step_depth + 2*overlap],
        [0,0, frame_thk_z/2 - outer_step_depth/2]);
    box([bbox_x - 2*outer_step_margin, bbox_y - 2*outer_step_margin, outer_step_depth + 4*overlap],
        [0,0, frame_thk_z/2 - outer_step_depth/2]);
  }
}

// Inner step transitions around the opening (a shallow ledge on the top face)
module inner_opening_step_ring() {
  difference() {
    box([opening_x + 2*inner_step_width, opening_y + 2*inner_step_width, inner_step_depth + 2*overlap],
        [0,0, frame_thk_z/2 - inner_step_depth/2]);
    box([opening_x, opening_y, inner_step_depth + 4*overlap],
        [0,0, frame_thk_z/2 - inner_step_depth/2]);
  }
}

// Boss pads at corners (reinforced pads)
module union_boss_pads() {
  union() {
    box([boss_w, boss_h, boss_z],
        [-bbox_x/2 + boss_w/2 + boss_inset,  bbox_y/2 - boss_h/2 - boss_inset, 0]);
    box([boss_w, boss_h, boss_z],
        [-bbox_x/2 + boss_w/2 + boss_inset, -bbox_y/2 + boss_h/2 + boss_inset, 0]);
    box([boss_w, boss_h, boss_z],
        [ bbox_x/2 - boss_w/2 - boss_inset,  bbox_y/2 - boss_h/2 - boss_inset, 0]);
    box([boss_w, boss_h, boss_z],
        [ bbox_x/2 - boss_w/2 - boss_inset, -bbox_y/2 + boss_h/2 + boss_inset, 0]);
  }
}

// Small alignment nubs (kept connected by placing on faces with slight overlap)
module union_alignment_nubs() {
  union() {
    cyl(nub_d/2, nub_h + 2*overlap,
        [-bbox_x/2 + outer_step_margin + nub_d/2, 0,  frame_thk_z/2 - nub_h/2]);
    cyl(nub_d/2, nub_h + 2*overlap,
        [-bbox_x/2 + outer_step_margin + nub_d/2, 0, -frame_thk_z/2 + nub_h/2]);
  }
}

// Subtractive features
module central_rectangular_opening() {
  box([opening_x, opening_y, frame_thk_z + 4*overlap]);
}

// C-gap that opens the inner opening to the outside on the +X side
module c_shape_side_gap() {
  // Ensure it reaches the outer boundary and overlaps slightly
  gap_len_x = (bbox_x/2 - opening_x/2) + c_gap_w + 2*overlap;
  box([gap_len_x, opening_y + 2*inner_step_width + 2*overlap, frame_thk_z + 4*overlap],
      [opening_x/2 + gap_len_x/2 - overlap, 0, 0]);
}

// Corner chamfers (small corner nips)
module chamfer_cut(pos) {
  translate(pos)
    rotate([0,0,45])
      cube([chamfer, chamfer, frame_thk_z + 4*overlap], center=true);
}

// Cosmetic reliefs on top face
module cosmetic_reliefs() {
  union() {
    cyl(relief_d/2, relief_depth + 2*overlap,
        [0,  bbox_y/2 - outer_step_margin - relief_d/2, frame_thk_z/2 - relief_depth/2]);
    cyl(relief_d/2, relief_depth + 2*overlap,
        [0, -bbox_y/2 + outer_step_margin + relief_d/2, frame_thk_z/2 - relief_depth/2]);
  }
}

// Build
module union_additive_features() {
  union() {
    outer_frame_plate();
    outer_perimeter_step_ring();
    inner_opening_step_ring();
    union_boss_pads();
    union_alignment_nubs();
  }
}

module final_part() {
  difference() {
    union_additive_features();

    // Main through opening + C-gap
    central_rectangular_opening();
    c_shape_side_gap();

    // Reliefs and chamfers
    cosmetic_reliefs();

    chamfer_cut([-bbox_x/2 + chamfer/2,  bbox_y/2 - chamfer/2, 0]);
    chamfer_cut([ bbox_x/2 - chamfer/2,  bbox_y/2 - chamfer/2, 0]);
    chamfer_cut([-bbox_x/2 + chamfer/2, -bbox_y/2 + chamfer/2, 0]);
    chamfer_cut([ bbox_x/2 - chamfer/2, -bbox_y/2 + chamfer/2, 0]);
  }
}

final_part();

// Stepped H-like bracket/block (prismatic, sharp edges)
// Target bounding box: 31.8 x 31.8 x 15.8 mm

$fn = 48;

// -------------------- Parameters --------------------
bbox_x = 31.8;
bbox_y = 31.8;
bbox_z = 15.8;

// End blocks (left/right)
end_w = 11.5;          // X width of each end block
end_d = bbox_y;        // Y depth
end_h = bbox_z;        // Z height

// Central bridge (connects end blocks)
bridge_d = 14;         // Y depth of bridge (narrower than end blocks)

// Asymmetric pads (additive, create asymmetric top/bottom silhouette)
pad_w = 7;             // X
pad_d = 10;            // Y
pad_h = 3;             // Z
pad_offset_x = 4;      // X offset from center
pad_offset_y = 6;      // Y offset from center

// Shoulder steps/rebates (subtractive)
top_rebate_depth = 2.2;
top_rebate_w = 10;
top_rebate_d = 12;

bottom_rebate_depth = 2.0;
bottom_rebate_w = 9;
bottom_rebate_d = 10;

// Internal relief cutouts (subtractive, through Z)
relief_w = 6;
relief_d = 8;
relief_offset_y = 7;

// Small additional rebates (subtractive)
small_rebate_w = 6;
small_rebate_d = 6;
small_rebate_depth = 1.2;

// Robustness
overlap = 0.6;           // small overlap to guarantee connectivity
cut_clear = 0.25;        // extra depth for clean subtraction

// -------------------- Helpers --------------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Derived: ensure exact bbox in X by solving bridge width from bbox_x and end_w
// Total X = end_w + bridge_w + end_w
bridge_w = clamp(bbox_x - 2*end_w, 0.1, bbox_x);

// -------------------- Base solids --------------------
module end_block(sign=1) { // sign = -1 left, +1 right
    translate([sign*(bbox_x/2 - end_w/2), 0, 0])
        cube([end_w, end_d, end_h], center=true);
}

module central_bridge() {
    // Bridge spans exactly between end blocks; add tiny overlap in X for guaranteed union
    cube([bridge_w + 2*overlap, bridge_d, bbox_z], center=true);
}

module offset_pad_top() {
    // Additive pad on top face, offset in +X,+Y
    translate([ pad_offset_x,  pad_offset_y,  bbox_z/2 - pad_h/2])
        cube([pad_w, clamp(pad_d, 0.1, bbox_y), pad_h], center=true);
}

module offset_pad_bottom() {
    // Additive pad on bottom face, offset in -X,-Y (asymmetric overall)
    translate([-pad_offset_x, -pad_offset_y, -bbox_z/2 + pad_h/2])
        cube([pad_w, clamp(pad_d, 0.1, bbox_y), pad_h], center=true);
}

// -------------------- Subtractive features --------------------
module top_rebate() {
    translate([0, 0, bbox_z/2 - (top_rebate_depth + cut_clear)/2])
        cube([top_rebate_w, clamp(top_rebate_d, 0.1, bbox_y), top_rebate_depth + cut_clear], center=true);
}

module bottom_rebate() {
    translate([0, 0, -bbox_z/2 + (bottom_rebate_depth + cut_clear)/2])
        cube([bottom_rebate_w, clamp(bottom_rebate_d, 0.1, bbox_y), bottom_rebate_depth + cut_clear], center=true);
}

module internal_relief(sign=1) {
    // Through-cut relief near each end block, offset in Y opposite on each side
    translate([sign*(bbox_x/2 - end_w/2), -sign*relief_offset_y, 0])
        cube([relief_w, relief_d, bbox_z + 2*cut_clear], center=true);
}

module small_rebate_left_top() {
    translate([-(bbox_x/2 - end_w/2), 0, bbox_z/2 - (small_rebate_depth + cut_clear)/2])
        cube([small_rebate_w, small_rebate_d, small_rebate_depth + cut_clear], center=true);
}

module small_rebate_right_bottom() {
    translate([(bbox_x/2 - end_w/2), 0, -bbox_z/2 + (small_rebate_depth + cut_clear)/2])
        cube([small_rebate_w, small_rebate_d, small_rebate_depth + cut_clear], center=true);
}

// -------------------- Main body (ONE connected solid) --------------------
module main_body() {
    union() {
        end_block(-1);
        end_block( 1);
        central_bridge();
        offset_pad_top();
        offset_pad_bottom();
    }
}

// -------------------- Final model --------------------
difference() {
    main_body();

    // Shoulder steps
    top_rebate();
    bottom_rebate();

    // Internal reliefs (asymmetric pair)
    internal_relief(-1);
    internal_relief( 1);

    // Extra small rebates (diagonal/asymmetric)
    small_rebate_left_top();
    small_rebate_right_bottom();
}

// Symmetric double-ended wedge/clevis-like spacer with opposing flared arms
// and two opposing tapered triangular tunnels.
// Bounding box target: 54.5 x 22.2 x 29.5 mm (L x W x H)

$fn = 96;

// --- Target overall size ---
L = 54.5;
W = 22.2;
H = 29.5;

// --- Shape controls ---
center_L = 14.0;                 // short central block length
arm_L_each = (L - center_L)/2;   // computed to hit overall L

waist_W = 12.0;                  // narrow waist width (Y)
waist_H = 16.0;                  // narrow waist height (Z)

end_W = W;                       // end width (Y)
end_H = H;                       // end height (Z)

overlap = 0.8;                   // overlap to guarantee connectivity

// End chamfer depth along X (creates angled end faces)
end_chamfer = 3.0;

// Triangular tunnel parameters (tapering toward center)
tri_end_side = 14.0;             // triangle side at the end face
tri_center_side = 8.0;           // triangle side near the center (smaller)
tri_clear = 0.5;                 // clearance added to triangle size
tri_depth_each_end = arm_L_each; // tunnel depth from each end toward center

// Extra length for cutters to ensure clean subtraction
cut_extra = 1.0;

// ----------------- Helpers -----------------
function tri_h(side) = side * sqrt(3) / 2;

// Equilateral triangle centered at origin in YZ plane (2D polygon in YZ)
module tri2d(side) {
    s = side;
    h = tri_h(s);
    polygon(points=[
        [ 0,        2*h/3],
        [-s/2,     -h/3 ],
        [ s/2,     -h/3 ]
    ]);
}

// 2D trapezoid in XZ (for side-view hourglass), centered at origin.
// width at center = w0, width at ends = w1, total length = len
module trapezoid_xz(len, w0, w1) {
    polygon(points=[
        [-len/2, -w1/2],
        [ len/2, -w1/2],
        [ len/2,  w1/2],
        [-len/2,  w1/2]
    ]);
}

// Outer envelope: central + two arms, with true flare (hourglass/X in side views)
// Achieved by intersecting two orthogonal "hourglass prisms" (one controls Y vs X, one controls Z vs X)
module outer_envelope() {
    // Prism controlling Y flare along X (extruded in Z)
    module prismY() {
        linear_extrude(height=H + 2*cut_extra, center=true, convexity=10)
            polygon(points=[
                [-L/2, -end_W/2],
                [ L/2, -end_W/2],
                [ L/2,  end_W/2],
                [-L/2,  end_W/2]
            ]);
        // Replace above with true trapezoid in XY:
        // (OpenSCAD doesn't allow easy "variable width" rectangle without polygon)
    }

    // True trapezoid in XY (Y width varies with X)
    module prismY_true() {
        linear_extrude(height=H + 2*cut_extra, center=true, convexity=10)
            polygon(points=[
                [-L/2, -end_W/2],
                [-center_L/2, -waist_W/2],
                [ center_L/2, -waist_W/2],
                [ L/2, -end_W/2],
                [ L/2,  end_W/2],
                [ center_L/2,  waist_W/2],
                [-center_L/2,  waist_W/2],
                [-L/2,  end_W/2]
            ]);
    }

    // True trapezoid in XZ (Z height varies with X), extruded in Y
    module prismZ_true() {
        rotate([90,0,0])  // extrude along Y
            linear_extrude(height=W + 2*cut_extra, center=true, convexity=10)
                polygon(points=[
                    [-L/2, -end_H/2],
                    [-center_L/2, -waist_H/2],
                    [ center_L/2, -waist_H/2],
                    [ L/2, -end_H/2],
                    [ L/2,  end_H/2],
                    [ center_L/2,  waist_H/2],
                    [-center_L/2,  waist_H/2],
                    [-L/2,  end_H/2]
                ]);
    }

    // Intersect to get an "X/hourglass" silhouette in both side views
    intersection() {
        prismY_true();
        prismZ_true();
    }
}

// End chamfer cutters: subtract frustums to create angled end faces
module end_chamfer_cutter(side_sign=1) {
    x_end = side_sign * (L/2);
    x_c = x_end - side_sign*(end_chamfer/2);

    // Frustum along X: larger at outside, smaller inward
    // Use linear_extrude along X by rotating a 2D square in YZ.
    translate([x_c, 0, 0])
        rotate([0, 90*side_sign, 0])
            linear_extrude(
                height=end_chamfer + 2*cut_extra,
                center=true,
                convexity=10,
                scale=[(end_W - 2*end_chamfer)/end_W, (end_H - 2*end_chamfer)/end_H]
            )
                square([end_W + 2*cut_extra, end_H + 2*cut_extra], center=true);
}

// Tapered triangular tunnel from each end toward center (triangular through-opening)
module tri_tunnel(side_sign=1) {
    // Place the cutter so its outer face aligns with the end face at x = +/- L/2
    // With center=true extrusion, the extrude spans [x_mid - h/2, x_mid + h/2] in local X after rotation.
    // Choose x_mid so the outermost reaches the end face.
    h_ex = tri_depth_each_end + 2*cut_extra;
    x_mid = side_sign * (L/2 - h_ex/2 + cut_extra);

    translate([x_mid, 0, 0])
        rotate([0, 90*side_sign, 0])
            linear_extrude(
                height=h_ex,
                center=true,
                convexity=10,
                scale=( (tri_center_side + 2*tri_clear) / (tri_end_side + 2*tri_clear) )
            )
                tri2d(tri_end_side + 2*tri_clear);
}

// ----------------- Final model -----------------
difference() {
    // Base solid (single connected body)
    outer_envelope();

    // End chamfers
    end_chamfer_cutter(-1);
    end_chamfer_cutter(+1);

    // Two opposing tapered triangular tunnels (one from each end)
    tri_tunnel(-1);
    tri_tunnel(+1);
}

// Parameters
L = 60.4; //[30.2:120.8:0.05]
W = 20.55; //[10.275:41.1:0.05]
T = 8.4; //[4.2:16.8:0.05]
tip_L = 10.5; //[5.25:21:0.05]
body_L = 39.4; //[19.7:78.8:0.05]
tip_W = 20.55; //[10.275:41.1:0.05]
body_W = 14.8; //[7.4:29.6:0.05]
fin_out = 2.875; //[1.4375:5.75:0.025]
fin_L = 6.5; //[3.25:13:0.05]
fin_T = 2.4; //[1.2:4.8:0.05]
fin_offset_from_end = 4; //[2:8:0.05]
notch_depth = 1.2; //[0.6:2.4:0.05]
notch_L = 4; //[2:8:0.05]
notch_T = 3; //[1.5:6:0.05]
overlap = 0.8; //[0.5:2:0.05]
chamfer = 0.6; //[0.3:1.2:0.05]
fillet_r = 0.45; //[0.25:1:0.05]
detail_groove_w = 0.8; //[0.4:1.6:0.05]
detail_groove_d = 0.5; //[0.25:1.2:0.05]
detail_groove_margin = 2.2; //[1.1:4.4:0.05]

// Base Shapes
module main_body_rect_prism() {
  translate([0, 0, 0])
    cube([body_L, body_W, T], center=true);
}

module end_tip_wedge_left() {
  translate([-body_L/2 - tip_L/2 + overlap, 0, 0])
    rotate([0, 90, 0])
      cylinder(h=tip_L, r1=tip_W/2, r2=0, center=true);
}

module end_tip_wedge_right() {
  translate([body_L/2 + tip_L/2 - overlap, 0, 0])
    rotate([0, -90, 0])
      cylinder(h=tip_L, r1=tip_W/2, r2=0, center=true);
}

module side_fin_step_left_pos() {
  translate([-L/2 + fin_offset_from_end + fin_L/2, body_W/2 + fin_out/2 - overlap, T/2 - fin_T/2])
    cube([fin_L, fin_out, fin_T], center=true);
}

module side_fin_step_left_neg() {
  translate([-L/2 + fin_offset_from_end + fin_L/2, -(body_W/2 + fin_out/2 - overlap), T/2 - fin_T/2])
    cube([fin_L, fin_out, fin_T], center=true);
}

module side_fin_step_right_pos() {
  translate([L/2 - fin_offset_from_end - fin_L/2, body_W/2 + fin_out/2 - overlap, T/2 - fin_T/2])
    cube([fin_L, fin_out, fin_T], center=true);
}

module side_fin_step_right_neg() {
  translate([L/2 - fin_offset_from_end - fin_L/2, -(body_W/2 + fin_out/2 - overlap), T/2 - fin_T/2])
    cube([fin_L, fin_out, fin_T], center=true);
}

module end_notch_relief_left() {
  translate([-L/2 + notch_depth + notch_L/2, 0, T/2 - notch_T/2])
    cube([notch_L, W, notch_T], center=true);
}

module end_notch_relief_right() {
  translate([L/2 - notch_depth - notch_L/2, 0, T/2 - notch_T/2])
    cube([notch_L, W, notch_T], center=true);
}

module surface_detail_lines_groove1() {
  translate([0, W/2 - detail_groove_margin - detail_groove_w/2, T/2 - detail_groove_d/2])
    cube([body_L, detail_groove_w, detail_groove_d], center=true);
}

module surface_detail_lines_groove2() {
  translate([0, -(W/2 - detail_groove_margin - detail_groove_w/2), T/2 - detail_groove_d/2])
    cube([body_L, detail_groove_w, detail_groove_d], center=true);
}

module edge_chamfers_kernel() {
  sphere(r=chamfer);
}

module small_fillet_rounding_kernel() {
  sphere(r=fillet_r);
}

// Operations
module side_fin_step_left_pair() {
  union() {
    side_fin_step_left_pos();
    side_fin_step_left_neg();
  }
}

module side_fin_step_right_pair() {
  union() {
    side_fin_step_right_pos();
    side_fin_step_right_neg();
  }
}

module arrow_raw_union() {
  union() {
    main_body_rect_prism();
    end_tip_wedge_left();
    end_tip_wedge_right();
    side_fin_step_left_pair();
    side_fin_step_right_pair();
  }
}

module arrow_with_notches() {
  difference() {
    arrow_raw_union();
    end_notch_relief_left();
    end_notch_relief_right();
  }
}

module arrow_with_surface_detail_lines() {
  difference() {
    arrow_with_notches();
    surface_detail_lines_groove1();
    surface_detail_lines_groove2();
  }
}

// Final Output
minkowski() {
  arrow_with_surface_detail_lines();
  edge_chamfers_kernel();
}

minkowski() {
  arrow_with_surface_detail_lines();
  small_fillet_rounding_kernel();
}

// Bounding box targets (mm)
bbox_X = 23.12; //[11.56:46.24:0.01]
bbox_Y = 10.31; //[5.155:20.62:0.01]
bbox_Z = 72.41; //[36.205:144.82:0.01]

// Main tapered arm (elongated along Z)
arm_L = bbox_Z; //[36.205:144.82:0.01]
arm_W_end1 = 8.5; //[4.25:17:0.01]   // X width near -Z
arm_W_end2 = 6;   //[3:12:0.01]      // X width near +Z
arm_T = 6.8;      //[3.4:13.6:0.01]  // Y thickness

// Fin / blade
fin_thk = 2; //[1:4:0.01]                 // thickness in X
fin_span = bbox_X; //[11.56:46.24:0.01]   // overall X span target (used to size fin reach)
fin_drop = bbox_Y; //[5.155:20.62:0.01]   // overall Y drop target (used for profile)
fin_L_along_arm = 18; //[9:36:0.01]       // length along Z
fin_pos_from_end = 6; //[3:12:0.01]       // from -Z end
fin_angle_deg = 35; //[10:70:1]           // rotate about X for acute angle
overlap = 1; //[0.5:2:0.1]

// ---------- Helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// ---------- Base Shapes ----------
module tapered_prismatic_arm() {
  // True prismatic taper: hull between two end cross-sections at z = +/- arm_L/2
  hull() {
    translate([0, 0, -arm_L/2])
      cube([arm_W_end1, arm_T, overlap], center=true);
    translate([0, 0,  arm_L/2])
      cube([arm_W_end2, arm_T, overlap], center=true);
  }
}

// Fin profile in Y-Z, extruded in X (thickness)
module fin_profile_extrude(fin_reach_y) {
  // Right triangle in Y-Z: along +Z and down in -Y
  linear_extrude(height=fin_thk, center=true)
    polygon(points=[
      [0, 0],
      [fin_L_along_arm, 0],
      [0, -fin_reach_y]
    ]);
}

// ---------- Placement / Connectivity ----------
module triangular_fin_blade_connected() {
  // Size fin so overall X span stays within bbox_X:
  // total X extent ≈ max(arm width) + fin thickness + fin lateral offset.
  // Here fin is attached to +X side; its outer face should not exceed bbox_X/2.
  arm_max_w = max(arm_W_end1, arm_W_end2);
  fin_center_x = arm_max_w/2 + fin_thk/2 - overlap; // ensures overlap into arm
  x_outer = fin_center_x + fin_thk/2;
  x_target_outer = bbox_X/2;
  // If arm already exceeds bbox_X, keep fin minimal; otherwise keep within bbox.
  x_margin = x_target_outer - x_outer;
  // Use this margin to set fin vertical reach (visual blade size) but clamp to bbox_Y.
  fin_reach_y = clamp(fin_drop, 0.6*bbox_Y, bbox_Y);

  // Put fin root near -Z end; fin local Z runs [0..fin_L], so center at root + fin_L/2
  fin_root_z = -arm_L/2 + fin_pos_from_end;
  fin_center_z = fin_root_z + fin_L_along_arm/2;

  // Attach at mid-thickness in Y so rotation makes it project up/down
  fin_center_y = 0;

  // Interface "weld" block to guarantee manifold union (overlaps both parts)
  // Place at fin root, spanning across arm thickness and fin thickness.
  weld_x = arm_max_w/2 - overlap/2;
  weld_y = 0;
  weld_z = fin_root_z + overlap/2;

  union() {
    translate([fin_center_x, fin_center_y, fin_center_z])
      rotate([fin_angle_deg, 0, 0])
        fin_profile_extrude(fin_reach_y);

    translate([weld_x, weld_y, weld_z])
      cube([fin_thk + 2*overlap, arm_T + 2*overlap, fin_thk + 2*overlap], center=true);
  }
}

// ---------- Final Model ----------
union() {
  tapered_prismatic_arm();
  triangular_fin_blade_connected();
}

// Parameters
L = 55.53; //[27.765:111.06:0.01]
W = 36.17; //[18.085:72.34:0.01]
T = 8.66; //[4.33:17.32:0.01]
tip_width = 0.6; //[0.3:1.2:0.01]
flange_w = 3.0; //[1.5:6.0:0.1]
flange_h = 1.6; //[0.8:3.2:0.1]
end_lip_len = 6.0; //[3.0:12.0:0.1]
end_lip_h = 2.0; //[1.0:4.0:0.1]
overlap = 1.0; //[0.5:2.0:0.1]
chamfer = 0.8; //[0.3:1.6:0.1]
fillet_r = 0.9; //[0.3:1.8:0.1]
tip_flat_len = 1.2; //[0.6:2.4:0.1]

// Base Shapes
module tapered_wedge_main_body() {
  linear_extrude(height=T) {
    polygon(points=[
      [-L/2, -W/2],
      [-L/2, W/2],
      [L/2, tip_width/2],
      [L/2, -tip_width/2]
    ]);
  }
}

module longitudinal_edge_step_flange() {
  linear_extrude(height=flange_h) {
    polygon(points=[
      [-L/2, W/2 - flange_w],
      [-L/2, W/2],
      [L/2, tip_width/2],
      [L/2, tip_width/2 - flange_w]
    ]);
  }
}

module wide_end_perpendicular_end_face_lip() {
  translate([-L/2 + end_lip_len/2 - overlap, 0, T/2 - end_lip_h/2])
    cube([end_lip_len, W, end_lip_h], center=true);
}

module small_tip_flattening_cutter() {
  translate([L/2 - tip_flat_len/2, 0, 0])
    cube([tip_flat_len, W*2, T*2], center=true);
}

module edge_chamfer_cutter_top_long() {
  rotate([0, 90, 0])
    translate([0, 0, T/2 - chamfer])
      linear_extrude(height=L + 2*overlap) {
        polygon(points=[
          [0, 0],
          [chamfer, 0],
          [0, chamfer]
        ]);
      }
}

module edge_chamfer_cutter_top_short() {
  rotate([-90, 0, 0])
    translate([-L/2 + end_lip_len - overlap, 0, T/2 - chamfer])
      linear_extrude(height=W + 2*overlap) {
        polygon(points=[
          [0, 0],
          [chamfer, 0],
          [0, chamfer]
        ]);
      }
}

module fillet_roundovers_sphere() {
  sphere(r=fillet_r);
}

// Operations
module main_plus_flange() {
  union() {
    tapered_wedge_main_body();
    longitudinal_edge_step_flange();
  }
}

module main_flange_plus_lip() {
  union() {
    main_plus_flange();
    wide_end_perpendicular_end_face_lip();
  }
}

module with_tip_flattening() {
  difference() {
    main_flange_plus_lip();
    small_tip_flattening_cutter();
  }
}

module with_edge_chamfers() {
  difference() {
    with_tip_flattening();
    edge_chamfer_cutter_top_long();
    edge_chamfer_cutter_top_short();
  }
}

// Final Output
minkowski() {
  with_edge_chamfers();
  fillet_roundovers_sphere();
}
